        self.text(927, 36, f'{used}/{supply}', 18, COLORS['red'] if used > supply else COLORS['blue'], True)
        self.text(1040, 15, 'CORE INTEGRITY', 9, COLORS['muted'], True)
        self.rect(1040, 42, 203, 10, '#354659')
        self.rect(1040, 42, 203 * w.corehp / w.coremax, 10, COLORS['green'])
        self.text(1257, 34, f'{int(w.corehp)} / {w.coremax}', 11, COLORS['muted'])
        self.text(26, 88, w.message if w.message_time else 'Build • salvage • upgrade • defend', 12, COLORS['gold'] if w.message_time else COLORS['muted'])

