@dataclass
class Camera:
    x: float = LEFT + NX * TILE / 2
    y: float = TOP + NY * TILE / 2
    zoom: float = 1.0
    target_zoom: float = 1.0
    shake_x: float = 0.0
    shake_y: float = 0.0

    @property
    def center(self):
        return (LEFT + NX * TILE / 2, TOP + NY * TILE / 2)

    def project(self, x, y):
        cx, cy = self.center
        return (cx + (x - self.x) * self.zoom + self.shake_x, cy + (y - self.y) * self.zoom + self.shake_y)

    def unproject(self, x, y):
        cx, cy = self.center
        return (self.x + (x - cx - self.shake_x) / self.zoom, self.y + (y - cy - self.shake_y) / self.zoom)

    def clamp(self):
        cx, cy = self.center
        halfw = NX * TILE / (2 * self.zoom)
        halfh = NY * TILE / (2 * self.zoom)
        self.x = max(LEFT + halfw, min(LEFT + NX * TILE - halfw, self.x))
        self.y = max(TOP + halfh, min(TOP + NY * TILE - halfh, self.y))
        if self.zoom <= 1.001:
            self.x, self.y = (cx, cy)

    def update(self, dt):
        self.zoom += (self.target_zoom - self.zoom) * min(1, dt * 14)
        if abs(self.target_zoom - self.zoom) < 0.001:
            self.zoom = self.target_zoom
        self.clamp()

    def reset(self):
        self.x, self.y = self.center
        self.zoom = self.target_zoom = 1

class CanvasPool:
    """Reuse Canvas objects and update only changed coordinates or properties.

    Unlike deleting and recreating the whole scene, this preserves Tk objects
    and avoids thousands of allocations every frame. Fixed drawing layers keep
    reused items in the proper visual order when objects appear or disappear.
    """
    LAYERS = ('terrain', 'ground', 'actors', 'effects', 'masks', 'hud', 'modal', 'transition')

    def __init__(self, widget, app):
        self.widget = widget
        self.app = app
        self.layer = 'hud'
        self.pools = defaultdict(list)
        self.cursors = defaultdict(int)
        self.hidden = set()
        self.records = {}
        self.width = WIDTH
        self.height = HEIGHT
        self.calls = 0
        self.updated = 0
        self.sequence = defaultdict(list)
        self.previous_sequence = {}
        self.held = set()

    def begin(self):
        self.cursors.clear()
        self.sequence.clear()
        self.held.clear()
        self.calls = 0
        self.updated = 0

    def reuse_layer(self, name):
        self.held.add(name)
        self.sequence[name] = self.previous_sequence.get(name, [])

    def set_layer(self, name):
        self.layer = name

    def coordinates(self, values):
        out = []
        camera_layer = self.layer in ('terrain', 'ground', 'actors', 'effects')
        scale = self.app.scale
        ox, oy = self.app.offset
        for i in range(0, len(values), 2):
            x, y = (values[i], values[i + 1])
            if camera_layer:
                x, y = self.app.camera.project(x, y)
            out.extend((round(x * scale + ox, 2), round(y * scale + oy, 2)))
        return tuple(out)

    def create(self, kind, coords, options):
        self.calls += 1
        key = (self.layer, kind)
        index = self.cursors[key]
        self.cursors[key] += 1
        coords = self.coordinates(coords)
        options = dict(options)
        options['tags'] = (self.layer,)
        if kind == 'image':
            options.pop('width', None)
        if index == len(self.pools[key]):
            item = getattr(self.widget, 'create_' + kind)(*coords, **options)
            self.pools[key].append(item)
            self.records[item] = (coords, options)
            self.updated += 1
        else:
            item = self.pools[key][index]
            oldcoords, oldoptions = self.records[item]
            if oldcoords != coords:
                self.widget.coords(item, *coords)
                self.updated += 1
            changed = {name: value for name, value in options.items() if oldoptions.get(name) != value}
            if item in self.hidden:
                changed['state'] = 'normal'
                self.hidden.remove(item)
            if changed:
                self.widget.itemconfigure(item, **changed)
                self.updated += 1
            self.records[item] = (coords, options)
        self.sequence[self.layer].append(item)
        return item

    def create_rectangle(self, *coords, **options):
        return self.create('rectangle', coords, options)

    def create_oval(self, *coords, **options):
        return self.create('oval', coords, options)

    def create_polygon(self, *coords, **options):
        return self.create('polygon', coords, options)

    def create_line(self, *coords, **options):
        return self.create('line', coords, options)

    def create_text(self, *coords, **options):
        return self.create('text', coords, options)

    def create_image(self, *coords, **options):
        return self.create('image', coords, options)

    def end(self):
        for key, pool in self.pools.items():
            if key[0] in self.held:
                continue
            used = self.cursors.get(key, 0)
            for item in pool[used:]:
                if item not in self.hidden:
                    self.widget.itemconfigure(item, state='hidden')
                    self.hidden.add(item)
        for layer in self.LAYERS:
            order = self.sequence.get(layer, [])
            if order != self.previous_sequence.get(layer):
                for item in order:
                    self.widget.tag_raise(item)
                self.previous_sequence[layer] = list(order)
            self.widget.tag_raise(layer)

    def bind(self, *args, **kwargs):
        return self.widget.bind(*args, **kwargs)

    def winfo_width(self):
        return self.widget.winfo_width()

    def winfo_height(self):
        return self.widget.winfo_height()

class SpriteBank:
    """Embedded antialiased game art, sliced and cached entirely with Tk.

    The atlas is embedded below. PyCharm users only need this Python file.
    Size variants are cached once, never resampled during a normal frame.
    """
    CELL = 128
    SIZES = (24, 32, 40, 48, 56, 64, 80, 96, 128, 160, 192, 256)

    def __init__(self, master):
        self.master = master
        self.atlas = tk.PhotoImage(master=master, data=SPRITE_ATLAS_B64, format='png')
        self.bases = {}
        self.cache = {}
        self.pending = deque()
        self.failed = False
        for i in range(28):
            img = tk.PhotoImage(master=master, width=self.CELL, height=self.CELL)
            x, y = (i % 4 * self.CELL, i // 4 * self.CELL)
            img.tk.call(img, 'copy', self.atlas, '-from', x, y, x + self.CELL, y + self.CELL)
            self.bases[i] = img
        for i in range(28):
            self.pending.append((i, 48, False))
            self.pending.append((i, 64, False))
            self.pending.append((i, 48, True))

    def pick_size(self, size):
        return min(self.SIZES, key=lambda value: abs(value - size))

    def get(self, index, size, flip=False):
        size = self.pick_size(size)
        key = (index, size, bool(flip))
        if key in self.cache:
            return self.cache[key]
        base = self.bases[index]
        divisor = math.gcd(size, self.CELL)
        zoom = size // divisor
        subsample = self.CELL // divisor
        if zoom > 1:
            image = base.zoom(zoom, zoom).subsample(subsample, subsample)
        elif subsample > 1:
            image = base.subsample(subsample, subsample)
        else:
            image = base.copy()
        if flip:
            image = image.subsample(-1, 1)
        self.cache[key] = image
        return image

    def warm(self, budget=0.003):
        start = time.perf_counter()
        while self.pending and time.perf_counter() - start < budget:
            index, size, flip = self.pending.popleft()
            self.get(index, size, flip)
_BaseBuilding = Building

@dataclass
class Building(_BaseBuilding):

    def stats(self):
        key = tuple(self.paths)
        if getattr(self, '_stats_key', None) != key:
            self._stats_value = super().stats()
            self._stats_key = key
        return self._stats_value

@dataclass
class FloatingNotice:
    title: str
    body: str
    color: str
    remaining: float = 4.0
    age: float = 0.0

    def update(self, dt):
        self.age += dt
        self.remaining -= dt

