class SmoothWorld(World):
    """Retains the game rules while improving routing, targeting and feedback."""

    def __init__(self, mapid=0, difficulty='standard'):
        self.difficulty = difficulty
        self.notice_queue = []
        self.earned = set()
        self.record = defaultdict(float)
        self.undo_stack = []
        self.route_cache = None
        self.relay_cache_version = -1
        self.relay_cache = set()
        self.defer_routes = False
        self.pending_routes = False
        self.finished_wave = 0
        super().__init__(mapid)
        self.money = 1750
        self.materials = dict(metal=420, circuits=125, crystal=18)
        self.message = 'Build your first robots. Scroll to zoom; right-click cancels a tool.'
        self.message_time = 8

    def notify(self, title, body='', color=None):
        self.notice_queue.append(FloatingNotice(title, body, color or COLORS['green']))

    def connected_relays(self):
        if self.relay_cache_version != self.nav_version:
            self.relay_cache = super().connected_relays()
            self.relay_cache_version = self.nav_version
        return self.relay_cache

    def repath(self):
        if self.defer_routes:
            self.pending_routes = True
            return
        super().repath()
        self.pending_routes = False

    def neighbors(self, p):
        x, y = p
        result = World.neighbors(p)
        for dx, dy in ((-1, -1), (-1, 1), (1, -1), (1, 1)):
            n = (x + dx, y + dy)
            if not (0 <= n[0] < NX and 0 <= n[1] < NY):
                continue
            clear = True
            for q in ((x + dx, y), (x, y + dy)):
                b = self.buildings.get(q)
                if q in self.terrain or (b and (not (b.role == 'gate' and b.opened))):
                    clear = False
                    break
            if clear:
                result.append(n)
        return result

    def choose_target(self, b, candidates):
        mode = getattr(b, 'target_mode', 'first')
        if mode == 'strong':
            return max(candidates, key=lambda e: e.hp)
        if mode == 'fast':
            return max(candidates, key=lambda e: BUGS[e.name][1])
        if mode == 'near':
            return min(candidates, key=lambda e: distance(e.pos, b.pos))
        if mode == 'weak':
            return min(candidates, key=lambda e: e.hp)
        s = b.stats()
        return min(candidates, key=lambda e: (0 if not s.get('priority') or e.name in ('Beetle', 'Stag Beetle', 'Ladybug', 'Goliath Beetle') else 1, distance(e.pos, self.corepos)))

    def place(self, x, y, kind):
        result = super().place(x, y, kind)
        if result:
            self.undo_stack.append((x, y, kind, self.active))
            self.record['spent'] += SPECS[kind]['price']
            self.record['placed'] += 1
            self.notify(SPECS[kind]['name'] + ' deployed', f"−${SPECS[kind]['price']}  ·  right-click to stop building", SPECS[kind]['color'])
        return result

    def place_line(self, points, kind):
        self.defer_routes = True
        placed = []
        for x, y in points:
            if (x, y) in self.buildings:
                continue
            if super().place(x, y, kind):
                placed.append((x, y))
                self.undo_stack.append((x, y, kind, self.active))
                self.record['spent'] += SPECS[kind]['price']
                self.record['placed'] += 1
        self.defer_routes = False
        if self.pending_routes:
            self.repath()
        if placed:
            self.notify(f'{len(placed)} wall segments built', f"−${len(placed) * SPECS[kind]['price']}")
        return placed

    def undo(self):
        if self.active:
            self.say('Undo is available between waves. You can sell during combat.')
            return
        while self.undo_stack:
            x, y, kind, was_active = self.undo_stack.pop()
            b = self.buildings.get((x, y))
            if not b or b.kind != kind:
                continue
            if was_active or sum(b.paths) or b.hp < b.stats()['hp'] - 0.01:
                self.say('This building has been used. Sell it for the normal refund.')
                return
            self.buildings.pop((x, y))
            self.money += b.spec['price']
            for resource in self.materials:
                self.materials[resource] += b.spec.get(resource, 0)
            self.repath()
            self.notify('Build undone', 'Full construction cost returned.', COLORS['gold'])
            return
        self.say('No unused construction to undo.')

    def buy_upgrade(self, b, path):
        next_upgrade = b.next_upgrade(path)
        before = self.money
        result = super().buy_upgrade(b, path)
        if result:
            self.record['upgrades'] += 1
            self.record['spent'] += before - self.money
            self.notify(next_upgrade['name'], f"Installed on {b.spec['name']}  ·  −${next_upgrade['price']}", COLORS['gold'])
        return result

    def salvage(self, pos):
        before = sum(self.materials.values())
        super().salvage(pos)
        if sum(self.materials.values()) > before:
            self.record['salvages'] += 1
            self.notify('Materials recovered', 'Use mining rigs to automate extraction.', COLORS['gold'])

    def damage(self, e, amount, source=None, stats=None):
        before = e.hp
        was_dead = e.dead
        super().damage(e, amount, source, stats)
        if source and (not was_dead):
            dealt = max(0, min(before, before - e.hp))
            source.damage_dealt = getattr(source, 'damage_dealt', 0) + dealt
            self.record['damage'] += dealt
            if e.dead:
                source.kill_count = getattr(source, 'kill_count', 0) + 1
        if e.dead and (not was_dead) and (e.name == 'Goliath Beetle'):
            self.notify('GOLIATH DEFEATED', 'Clear the remaining escorts to secure the base.', COLORS['gold'])

    def start_wave(self):
        before = self.wave
        super().start_wave()
        if before == self.wave:
            return
        plan = WAVE_PLANS[self.wave - 1]
        names = list(self.queue)
        if plan.focus != 'Goliath Beetle':
            replace = min(len(names) // 3, 12)
            for i in range(replace):
                names[i * 3] = plan.focus
        names.extend([plan.focus if plan.focus != 'Goliath Beetle' else 'Stag Beetle'] * plan.count_bonus)
        self.queue = deque(names)
        self.undo_stack.clear()
        self.say(f'Wave {self.wave} • {plan.name}: {plan.description}')
        self.notify(f'WAVE {self.wave:02d} / {plan.name.upper()}', plan.description, COLORS['red'])
        if self.wave in (10, 20, 30):
            name = 'Beetle' if self.wave == 10 else 'Stag Beetle'
            self.queue.appendleft(name)
            self.elite_pending = True
        else:
            self.elite_pending = False

    def move_enemies(self, dt):
        old = {id(e): (e.angle, e.pos) for e in self.enemies}
        super().move_enemies(dt)
        buckets = defaultdict(list)
        for e in self.enemies:
            if id(e) in old:
                angle, pos = old[id(e)]
                delta = (e.angle - angle + math.pi) % math.tau - math.pi
                e.angle = angle + delta * min(1, dt * 13)
                e.last_pos = pos
            buckets[int(e.x), int(e.y)].append(e)
        for e in self.enemies:
            if e.dead or e.flying or e.stun:
                continue
            push_x = push_y = 0
            cell = (int(e.x), int(e.y))
            for dx in (-1, 0, 1):
                for dy in (-1, 0, 1):
                    for other in buckets.get((cell[0] + dx, cell[1] + dy), ()):
                        if other is e or other.flying:
                            continue
                        vx, vy = (e.x - other.x, e.y - other.y)
                        dist = math.hypot(vx, vy)
                        if 0.01 < dist < 0.4:
                            strength = (0.4 - dist) * dt * 1.8 / dist
                            push_x += vx * strength
                            push_y += vy * strength
            nx = e.x + max(-0.04, min(0.04, push_x))
            ny = e.y + max(-0.04, min(0.04, push_y))
            p = (int(nx), int(ny))
            if 0 <= nx < NX and 0 <= ny < NY and (p not in self.terrain) and (p not in self.buildings):
                e.x, e.y = (nx, ny)

    def retarget_projectiles(self):
        for p in self.projectiles:
            if not p['target'].dead or p['role'] == 'mortar':
                continue
            candidates = [e for e in self.enemies if not e.dead and distance(e.pos, p['dest']) < 2]
            if p['role'] == 'air':
                candidates = [e for e in candidates if e.flying]
            if candidates:
                p['target'] = min(candidates, key=lambda e: distance(e.pos, (p['x'], p['y'])))
                p['dest'] = p['target'].pos

    def achievement_progress(self, achievement):
        category = achievement.category
        if category == 'robots':
            return sum((b.kind < 12 for b in self.buildings.values()))
        if category == 'waves':
            return self.wave if not self.active else max(0, self.wave - 1)
        if category == 'kills':
            return self.kills
        if category == 'upgrades':
            return self.record['upgrades']
        if category == 'specialists':
            return sum((max(b.paths) >= 3 for b in self.buildings.values()))
        if category == 'mines':
            return sum((b.role == 'mine' for b in self.buildings.values()))
        if category == 'relays':
            return len(self.connected_relays())
        if category == 'walls':
            return sum((b.role == 'wall' for b in self.buildings.values()))
        return self.record['salvages']

    def check_achievements(self):
        for achievement in ACHIEVEMENTS:
            if achievement.key in self.earned:
                continue
            if self.achievement_progress(achievement) >= achievement.target:
                self.earned.add(achievement.key)
                self.money += achievement.reward
                self.notify('ACHIEVEMENT / ' + achievement.title, f'{achievement.description}  +${achievement.reward}', COLORS['gold'])

    def update(self, dt):
        before_ids = {id(e) for e in self.enemies}
        was_active = self.active
        self.retarget_projectiles()
        super().update(dt)
        self.record['time'] += dt
        if self.wave:
            plan = WAVE_PLANS[self.wave - 1]
            difficulty_factor = {'relaxed': 0.78, 'standard': 1.0, 'veteran': 1.22}[self.difficulty]
            for e in self.enemies:
                if id(e) not in before_ids:
                    multiplier = plan.health_bonus * difficulty_factor
                    e.hp *= multiplier
                    e.maxhp *= multiplier
                    e.speed_multiplier = plan.speed_bonus
                    if getattr(self, 'elite_pending', False):
                        e.hp *= 2.5
                        e.maxhp *= 2.5
                        e.elite = True
                        self.elite_pending = False
                        self.notify('ELITE INSECT', 'Concentrate your heavy weapons.', COLORS['red'])
        if was_active and (not self.active) and (not self.outcome):
            self.finished_wave = self.wave
            self.notify('WAVE CLEARED', f'${100 + self.wave * 18} + materials. Next: {WAVE_PLANS[min(39, self.wave)].name}', COLORS['green'])
        self.check_achievements()

class SaveManager:
    VERSION = 1
    VALID_DIFFICULTIES = ('relaxed', 'standard', 'veteran')

    def __init__(self, path=None):
        self.path = Path(path) if path else Path(__file__).resolve().with_name('swarmfall-save.json')

    def exists(self):
        return self.path.is_file()

    def serialize(self, w):
        if w.active or w.enemies:
            raise ValueError('Save between waves so the whole base can be restored cleanly.')
        return {'version': self.VERSION, 'map': w.mapid, 'difficulty': w.difficulty, 'wave': w.wave, 'money': w.money, 'materials': dict(w.materials), 'corehp': w.corehp, 'kills': w.kills, 'autoplay': w.autoplay, 'earned': sorted(w.earned), 'record': dict(w.record), 'deposits': [[x, y, d[1]] for (x, y), d in w.deposits.items()], 'buildings': [{'x': b.x, 'y': b.y, 'kind': b.kind, 'hp': b.hp, 'paths': list(b.paths), 'invested': b.invested, 'opened': b.opened, 'target': getattr(b, 'target_mode', 'first'), 'kills': getattr(b, 'kill_count', 0), 'damage': getattr(b, 'damage_dealt', 0)} for b in w.buildings.values()]}

    def save(self, w):
        data = self.serialize(w)
        temp = self.path.with_suffix('.tmp')
        temp.write_text(json.dumps(data, indent=2), encoding='utf-8')
        temp.replace(self.path)

    @staticmethod
    def integer(value, lo, hi, label):
        if not isinstance(value, int) or isinstance(value, bool) or (not lo <= value <= hi):
            raise ValueError('Invalid save field: ' + label)
        return value

    @staticmethod
    def number(value, lo, hi, label):
        if not isinstance(value, (int, float)) or not math.isfinite(value) or (not lo <= value <= hi):
            raise ValueError('Invalid save field: ' + label)
        return value

    def deserialize(self, data):
        if not isinstance(data, dict) or data.get('version') != self.VERSION:
            raise ValueError('This save version is not supported.')
        mapid = self.integer(data.get('map'), 0, 2, 'map')
        difficulty = data.get('difficulty', 'standard')
        if difficulty not in self.VALID_DIFFICULTIES:
            raise ValueError('Invalid difficulty.')
        w = SmoothWorld(mapid, difficulty)
        w.wave = self.integer(data.get('wave'), 0, 40, 'wave')
        w.money = self.integer(data.get('money'), 0, 10 ** 8, 'money')
        w.kills = self.integer(data.get('kills'), 0, 10 ** 7, 'kills')
        w.corehp = self.number(data.get('corehp'), 0, w.coremax, 'core integrity')
        materials = data.get('materials')
        if not isinstance(materials, dict):
            raise ValueError('Missing material inventory.')
        for key in w.materials:
            w.materials[key] = self.integer(materials.get(key), 0, 10 ** 8, key)
        entries = data.get('buildings')
        if not isinstance(entries, list) or len(entries) > NX * NY:
            raise ValueError('Invalid building list.')
        for entry in entries:
            if not isinstance(entry, dict):
                raise ValueError('Invalid building.')
            x = self.integer(entry.get('x'), 0, NX - 1, 'x')
            y = self.integer(entry.get('y'), 0, NY - 1, 'y')
            kind = self.integer(entry.get('kind'), 0, len(SPECS) - 1, 'kind')
            if (x, y) in w.buildings or (x, y) in w.terrain or (x, y) == w.core or ((x, y) in w.deposits) or ((x, y) in w.spawns):
                raise ValueError('Invalid occupied building tile.')
            paths = entry.get('paths')
            if not isinstance(paths, list) or len(paths) != 2:
                raise ValueError('Invalid upgrade paths.')
            paths = [self.integer(n, 0, 3, 'path tier') for n in paths]
            if min(paths) > 1 or (kind >= 12 and any(paths)):
                raise ValueError('Invalid crosspath configuration.')
            b = Building(x, y, kind)
            b.paths = paths
            b.hp = self.number(entry.get('hp'), 0.01, b.stats()['hp'], 'building health')
            b.invested = self.integer(entry.get('invested'), b.spec['price'], 10 ** 7, 'investment')
            b.opened = bool(entry.get('opened', False))
            mode = entry.get('target', 'first')
            b.target_mode = mode if mode in ('first', 'strong', 'fast', 'near', 'weak') else 'first'
            b.kill_count = self.integer(entry.get('kills', 0), 0, 10 ** 7, 'robot kills')
            b.damage_dealt = self.number(entry.get('damage', 0), 0, 10 ** 12, 'robot damage')
            w.buildings[x, y] = b
        deposits = data.get('deposits', [])
        if not isinstance(deposits, list) or len(deposits) > 30:
            raise ValueError('Invalid deposits.')
        for entry in deposits:
            if not isinstance(entry, list) or len(entry) != 3:
                raise ValueError('Invalid deposit.')
            x, y, amount = entry
            if (x, y) in w.deposits:
                w.deposits[x, y][1] = self.integer(amount, 0, 250, 'remaining resource')
        earned = data.get('earned', [])
        if not isinstance(earned, list):
            raise ValueError('Invalid achievements.')
        valid = {a.key for a in ACHIEVEMENTS}
        w.earned = {key for key in earned if isinstance(key, str) and key in valid}
        record = data.get('record', {})
        if not isinstance(record, dict):
            raise ValueError('Invalid mission statistics.')
        for key, value in record.items():
            if key in ('time', 'damage', 'spent', 'placed', 'upgrades', 'salvages'):
                w.record[key] = self.number(value, 0, 10 ** 12, 'statistic')
        w.autoplay = bool(data.get('autoplay', False))
        w.intermission = 8
        w.repath()
        if w.wave == 40:
            w.outcome = 'won'
        w.say('Base restored. Ready when you are.')
        return w

    def load(self):
        if self.path.stat().st_size > 2000000:
            raise ValueError('Save file is unexpectedly large.')
        return self.deserialize(json.loads(self.path.read_text(encoding='utf-8')))

def line_tiles(a, b):
    """Integer Bresenham line, used for wall previews and one-click batches."""
    x, y = a
    tx, ty = b
    dx = abs(tx - x)
    dy = -abs(ty - y)
    sx = 1 if x < tx else -1
    sy = 1 if y < ty else -1
    error = dx + dy
    points = []
    while True:
        points.append((x, y))
        if (x, y) == (tx, ty):
            break
        twice = 2 * error
        if twice >= dy:
            error += dy
            x += sx
        if twice <= dx:
            error += dx
            y += sy
    return points
from concurrent.futures import ThreadPoolExecutor
from collections import OrderedDict
import zlib

class TextureBank:
    """Resize painted terrain away from Tk's event thread; cache finished images."""
    WIDTH = 476
    HEIGHT = 374

    def __init__(self, master):
        self.master = master
        self.raw = [zlib.decompress(base64.b64decode(data)) for data in TERRAIN_TEXTURE_DATA]
        self.default = {}
        self.cache = OrderedDict()
        self.executor = ThreadPoolExecutor(max_workers=1, thread_name_prefix='swarmfall-terrain')
        self.future = None
        self.wanted = None
        self.closed = False
        for index, data in enumerate(self.raw):
            ppm = f'P6\n{self.WIDTH} {self.HEIGHT}\n255\n'.encode() + data
            image = tk.PhotoImage(master=master, data=ppm, format='PPM')
            self.default[index] = image.zoom(2, 2)
            self.cache[index, 952] = self.default[index]

    @classmethod
    def resize(cls, data, target_width):
        target_height = round(target_width * cls.HEIGHT / cls.WIDTH)
        offsets = [min(cls.WIDTH - 1, int(x * cls.WIDTH / target_width)) * 3 for x in range(target_width)]
        rows = []
        for y in range(cls.HEIGHT):
            row = data[y * cls.WIDTH * 3:(y + 1) * cls.WIDTH * 3]
            rows.append(b''.join((row[p:p + 3] for p in offsets)))
        output = b''.join((rows[min(cls.HEIGHT - 1, int(y * cls.HEIGHT / target_height))] for y in range(target_height)))
        return f'P6\n{target_width} {target_height}\n255\n'.encode() + output

    def get(self, index, width):
        width = max(384, min(3072, round(width / 32) * 32))
        key = (index, width)
        if key in self.cache:
            self.cache.move_to_end(key)
            return self.cache[key]
        self.wanted = key
        available = [k for k in self.cache if k[0] == index]
        if available:
            closest = min(available, key=lambda k: abs(k[1] - width))
            return self.cache[closest]
        return self.default[index]

    def pump(self):
        if self.closed:
            return
        if self.future is not None and self.future.done():
            key, future = (self.future_key, self.future)
            self.future = None
            try:
                ppm = future.result()
                self.cache[key] = tk.PhotoImage(master=self.master, data=ppm, format='PPM')
                while len(self.cache) > 6:
                    self.cache.popitem(last=False)
            except (RuntimeError, ValueError, tk.TclError):
                pass
        if self.future is None and self.wanted is not None:
            key = self.wanted
            self.wanted = None
            if key not in self.cache:
                self.future_key = key
                self.future = self.executor.submit(self.resize, self.raw[key[0]], key[1])

    def close(self):
        self.closed = True
        self.executor.shutdown(wait=False, cancel_futures=True)

class PremiumApp(PolishedApp):
    """Single-file art edition with responsive controls and retained rendering."""

    def __init__(self):
        self.camera = Camera()
        self.sprite_bank = None
        self.texture_bank = None
        self.raw_canvas = None
        self.ready = False
        self.difficulty = 'standard'
        self.notices = []
        self.save_manager = SaveManager()
        self.wall_start = None
        self.wall_end = None
        self.pan_anchor = None
        self.accumulator = 0
        self.fps_average = 60
        self.last_frame_ms = 16.67
        self.show_codex = False
        self.codex_tab = 'robots'
        self.codex_index = 0
        self.codex_page = 0
        self.fullscreen = False
        self.tooltip_timer = 0
        self.tooltip_key = None
        self.hover_card = None
        self.attack_pulses = {}
        self.floating_dollars = []
        self.time_scale = 1
        self.frame_counter = 0
        super().__init__()
        self.raw_canvas = self.canvas
        self.canvas = CanvasPool(self.raw_canvas, self)
        self.sprite_bank = SpriteBank(self.root)
        self.texture_bank = TextureBank(self.root)
        self.world = SmoothWorld()
        self.title_world = SmoothWorld()
        self.ready = True
        self.raw_canvas.bind('<MouseWheel>', self.wheel)
        self.raw_canvas.bind('<Button-4>', lambda e: self.wheel(e, 1))
        self.raw_canvas.bind('<Button-5>', lambda e: self.wheel(e, -1))
        self.raw_canvas.bind('<Button-2>', self.pan_start)
        self.raw_canvas.bind('<B2-Motion>', self.pan_move)
        self.raw_canvas.bind('<ButtonRelease-2>', self.pan_stop)
        self.raw_canvas.bind('<ButtonRelease-1>', self.release)
        self.raw_canvas.bind('<Control-Button-1>', self.cancel)
        self.root.bind('<FocusOut>', self.focus_out)

    def focus_out(self, event):
        if event.widget is self.root and self.state == 'play' and (not self.world.outcome):
            self.paused = True
            self.pause_age = 0

    def tile(self, p):
        x, y = self.camera.unproject(*p)
        return (int((x - LEFT) // TILE), int((y - TOP) // TILE))

    @staticmethod
    def on_board(pos):
        return LEFT <= pos[0] < LEFT + NX * TILE and TOP <= pos[1] < TOP + NY * TILE

    def wheel(self, event, direction=None):
        if self.state != 'play' or self.paused or self.show_codex or self.show_help or self.transition:
            return
        self.hover = self.logical(event)
        if not self.on_board(self.hover):
            return
        if direction is None:
            direction = 1 if event.delta > 0 else -1
        old = self.camera.unproject(*self.hover)
        self.camera.target_zoom = max(1, min(2.2, self.camera.target_zoom + direction * 0.15))
        self.camera.x += (old[0] - self.camera.x) * 0.13 * direction
        self.camera.y += (old[1] - self.camera.y) * 0.13 * direction
        self.camera.clamp()

    def pan_start(self, event):
        pos = self.logical(event)
        if self.state == 'play' and self.on_board(pos) and (not self.paused):
            self.pan_anchor = pos

    def pan_move(self, event):
        if self.pan_anchor is None:
            return
        pos = self.logical(event)
        self.camera.x -= (pos[0] - self.pan_anchor[0]) / self.camera.zoom
        self.camera.y -= (pos[1] - self.pan_anchor[1]) / self.camera.zoom
        self.camera.clamp()
        self.pan_anchor = pos

    def pan_stop(self, event):
        self.pan_anchor = None

    def cancel(self, event=None):
        self.wall_start = None
        self.wall_end = None
        self.pan_anchor = None
        super().cancel(event)

    def key(self, event):
        key = event.keysym.lower()
        control = bool(event.state & 4) if hasattr(event, 'state') else False
        if key == 'f11':
            self.fullscreen = not self.fullscreen
            self.root.attributes('-fullscreen', self.fullscreen)
            return
        if self.transition:
            return
        if self.show_codex:
            if key in ('escape', 'f2'):
                self.show_codex = False
            return
        if key == 'f2':
            self.show_codex = True
            return
        if key == 'f5':
            self.action(('save',))
            return
        if key == 'f9':
            self.action(('load',))
            return
        if self.show_help:
            super().key(event)
            return
        if key == 'escape' and (self.build is not None or self.selected):
            self.cancel()
            return
        if self.state == 'play' and (not self.paused) and (not self.world.outcome):
            if control and key == 'z':
                self.world.undo()
                return
            if key == 'f':
                self.camera.reset()
                return
            if key == 'r':
                self.action(('build', 0))
                return
            if key == 'w':
                self.action(('build', 12))
                return
            b = self.world.buildings.get(self.selected)
            if key == 'c' and b:
                self.action(('build', b.kind))
                return
            if key == 'e' and b:
                self.world.repair(b)
                return
            if key in ('u', 'i') and b and (b.kind < 12):
                self.world.buy_upgrade(b, 0 if key == 'u' else 1)
                return
        super().key(event)

    def click(self, event):
        if not self.ready or self.transition:
            return
        self.hover = self.logical(event)
        x, y = self.hover
        for rect, action, enabled in reversed(self.buttons):
            if rect[0] <= x <= rect[0] + rect[2] and rect[1] <= y <= rect[1] + rect[3]:
                if enabled:
                    self.action(action)
                return
        if self.show_help or self.show_codex or self.state != 'play' or self.paused or self.world.outcome:
            return
        if not self.on_board(self.hover):
            return
        gx, gy = self.tile(self.hover)
        b = self.world.buildings.get((gx, gy))
        if b:
            self.selected = (gx, gy)
            self.build = None
            self.wall_start = self.wall_end = None
            return
        if self.build == 'salvage':
            self.world.salvage((gx, gy))
        elif self.build == 12:
            self.wall_start = self.wall_end = (gx, gy)
        elif isinstance(self.build, int):
            self.world.place(gx, gy, self.build)
        else:
            self.selected = None

    def drag(self, event):
        self.hover = self.logical(event)
        if self.wall_start is not None and self.on_board(self.hover) and (not self.paused):
            self.wall_end = self.tile(self.hover)

    def release(self, event):
        if self.wall_start is None:
            return
        if self.state == 'play' and (not self.paused) and (not self.show_help) and (not self.show_codex):
            points = line_tiles(self.wall_start, self.wall_end or self.wall_start)
            self.world.place_line(points, 12)
        self.wall_start = self.wall_end = None

    def action(self, a):
        if self.transition:
            return
        kind = a[0]
        if kind == 'difficulty':
            self.difficulty = a[1]
            return
        if kind == 'codex':
            self.show_codex = not self.show_codex
            return
        if kind == 'codextab':
            self.codex_tab = a[1]
            self.codex_index = 0
            self.codex_page = 0
            return
        if kind == 'codexindex':
            self.codex_index = a[1]
            return
        if kind == 'codexpage':
            self.codex_page = a[1]
            return
        if kind == 'target':
            b = self.world.buildings.get(self.selected)
            if b:
                modes = ('first', 'strong', 'fast', 'near', 'weak')
                current = getattr(b, 'target_mode', 'first')
                b.target_mode = modes[(modes.index(current) + 1) % len(modes)]
                self.world.notify('Target priority', b.target_mode.upper(), COLORS['blue'])
            return
        if kind == 'minimap':
            self.recenter_from_minimap()
            return
        if kind == 'view':
            self.camera.reset()
            return
        if kind == 'undo':
            self.world.undo()
            return
        if kind == 'save':
            if self.state != 'play':
                return
            try:
                self.save_manager.save(self.world)
                self.world.notify('BASE SAVED', 'F9 restores this between-wave snapshot.', COLORS['green'])
            except (OSError, ValueError) as exc:
                self.world.notify('Could not save', str(exc), COLORS['red'])
            return
        if kind == 'load':
            try:
                restored = self.save_manager.load()
            except (OSError, ValueError, TypeError, KeyError) as exc:
                if self.state == 'play':
                    self.world.notify('Could not load', str(exc), COLORS['red'])
                return
            self.world = restored
            self._terrain_key = None
            self.state = 'play'
            self.paused = True
            self.pause_age = 0
            self.show_codex = self.show_help = False
            self.selected = self.build = None
            self.notices = []
            self.previous_wave = self.world.wave
            self.camera.reset()
            self.accumulator = 0
            return
        if kind == 'build':
            self.wall_start = self.wall_end = None
        if kind in ('resume', 'pause'):
            self.accumulator = 0
        super().action(a)

    def sprite(self, index, x, y, size, flip=False):
        if self.sprite_bank is None:
            return False
        camera_layer = getattr(self.canvas, 'layer', 'hud') in ('terrain', 'ground', 'actors', 'effects')
        physical_size = size * self.scale * (self.camera.zoom if camera_layer else 1)
        image = self.sprite_bank.get(index, physical_size, flip)
        self.canvas.create_image(x, y, image=image, anchor='center')
        return True

    def draw_robot(self, b, x, y, scale=1):
        index = b.kind if b.kind < 12 else 26 if b.role == 'generator' else 27 if b.role == 'shield' else None
        if index is None:
            super().draw_robot(b, x, y, scale)
            return
        size = (53 if b.kind < 12 else 52) * scale
        hover = math.sin(self.real_time * 2.5 + b.x) * 0.35 * scale
        recoil = min(1, b.animation / 0.15) * 1.4 * scale
        flip = math.cos(b.angle) < -0.1
        self.sprite(index, x - recoil * (-1 if flip else 1), y - 8 * scale + hover, size, flip)
        if b.kind >= 12:
            if b.role == 'generator':
                r = (7 + math.sin(self.real_time * 2) * 1.5) * scale
                self.oval(x - r, y - r * 0.55 + 9 * scale, 2 * r, r * 1.1, '', '#a6efdc', 1)
            return
        for path, tier in enumerate(b.paths):
            for i in range(tier):
                px = x + (-8 + i * 7) * scale
                py = y + (20 + path * 5) * scale
                self.polygon([(px, py - 2 * scale), (px + 3 * scale, py), (px, py + 2 * scale), (px - 3 * scale, py)], '#f6d492' if path == 0 else '#c4aff7')
        if b.shield > 0:
            rr = 23 * scale
            self.oval(x - rr, y - rr - 9 * scale, rr * 2, rr * 2, '', '#bdcaff', 0.8)
        if b.jam > 0:
            self.text(x, y - 37 * scale, 'DISRUPTED', 7 * scale, '#f5da99', True, anchor='center')
        if b.hp < b.stats()['hp']:
            ww = 29 * scale
            self.roundrect(x - ww / 2, y - 37 * scale, ww, 3 * scale, '#40545d', r=1)
            self.roundrect(x - ww / 2, y - 37 * scale, max(0.3, ww * b.hp / b.stats()['hp']), 3 * scale, '#a9edb1', r=1)

    def draw_bug(self, e, x, y, scale=1):
        index = 12 + list(BUGS).index(e.name)
        size = (BUGS[e.name][3] * 3.4 + 9) * scale
        if e.name == 'Goliath Beetle':
            size = 122 * scale
        moving = not e.stun and (not e.dead)
        bob = math.sin(self.real_time * (13 if e.flying else 10) + e.x * 3) * (0.9 if not e.flying else 2.0) * scale if moving else 0
        flip = math.cos(e.angle) < 0
        self.sprite(index, x, y - 5 * scale + bob, size, flip)
        if e.flying and self.quality:
            for side in (-1, 1):
                spread = (0.6 + abs(math.sin(self.real_time * 29)) * 0.4) * BUGS[e.name][3] * scale
                self.line([(x, y - 4 * scale), (x + side * spread, y - 10 * scale - spread * 0.2)], '#cfede3', 0.65)
        if e.slow_time:
            r = (BUGS[e.name][3] + 5) * scale
            self.oval(x - r, y - r, r * 2, r * 2, '', '#b9eff7', 1)
        if e.stun:
            for i in range(3):
                a = self.real_time * 3 + i * 2.1
                self.text(x + math.cos(a) * 12 * scale, y - size * 0.35 - 7 * scale, '+', 9 * scale, '#efffdb', True, anchor='center')
        if e.marked:
            self.line([(x - 9 * scale, y - size * 0.4 - 4 * scale), (x, y - size * 0.4 + 1 * scale), (x + 9 * scale, y - size * 0.4 - 4 * scale)], '#d0b8ff', 1)
        if e.burn_time:
            for i in range(3):
                a = self.real_time * 8 + i * 2.2
                px = x + math.sin(a) * 9 * scale
                py = y - 5 * scale + math.cos(a) * 4 * scale
                self.polygon([(px - 3 * scale, py), (px, py - 11 * scale), (px + 4 * scale, py)], '#ffbd73')
        if getattr(e, 'elite', False):
            self.text(x, y - size * 0.45 - 8 * scale, 'ELITE', 8 * scale, '#ffe4a3', True, anchor='center')
        if e.hp < e.maxhp and e.name != 'Goliath Beetle':
            ww = max(24, size * 0.5)
            self.roundrect(x - ww / 2, y - size * 0.4 - 4 * scale, ww, 3 * scale, '#4c584e', r=1)
            self.roundrect(x - ww / 2, y - size * 0.4 - 4 * scale, max(0.1, ww * e.hp / e.maxhp), 3 * scale, '#d3efad', r=1)

    def draw_environment(self, w):
        base = ('#a4b582', '#c5a37a', '#95b3a1')[w.mapid]
        self.roundrect(LEFT - 6, TOP - 6, NX * TILE + 12, NY * TILE + 12, '#0a1825', r=10)
        self.rect(LEFT, TOP, NX * TILE, NY * TILE, base)
        if self.texture_bank is not None:
            width = NX * TILE * self.scale * self.camera.zoom
            image = self.texture_bank.get(w.mapid, width)
            x, y = self.point((NX / 2, NY / 2))
            self.canvas.create_image(x, y, image=image, anchor='center')
        if self.show_grid or self.build is not None:
            for gx in range(NX + 1):
                self.line([(LEFT + gx * TILE, TOP), (LEFT + gx * TILE, TOP + NY * TILE)], '#c7d4b1', 0.35)
            for gy in range(NY + 1):
                self.line([(LEFT, TOP + gy * TILE), (LEFT + NX * TILE, TOP + gy * TILE)], '#c7d4b1', 0.35)
        for x, y in sorted(w.terrain):
            px, py = self.point((x, y))
            seed = (x * 17 + y * 41) % 13
            if w.mapid == 2:
                self.rect(px, py, TILE + 1, TILE + 1, '#6caeb6')
                for dx, dy in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                    if (x + dx, y + dy) not in w.terrain:
                        if dx:
                            self.rect(px + (0 if dx < 0 else TILE - 3), py, 3, TILE, '#d8d9aa')
                        else:
                            self.rect(px, py + (0 if dy < 0 else TILE - 3), TILE, 3, '#d8d9aa')
                wave = math.sin(self.real_time * 1.5 + x + y) * 3
                self.line([(px + 4 + wave, py + 11), (px + 15 + wave, py + 10), (px + 22 + wave, py + 12)], '#a1d0cf', 1)
                self.line([(px + 11 - wave, py + 24), (px + 25 - wave, py + 24)], '#80bec2', 1)
            else:
                shadow = '#8b9e76' if w.mapid == 0 else '#b29874'
                self.oval(px + 1, py + 20, 36, 17, shadow)
                rock = '#7e8e7c' if w.mapid == 0 else '#a48b70'
                self.polygon([(px - 2, py + 26), (px + 5, py + 8), (px + 16, py + 2), (px + 29, py + 7), (px + 36, py + 27), (px + 24, py + 33), (px + 7, py + 31)], rock)
                self.polygon([(px + 5, py + 8), (px + 16, py + 2), (px + 29, py + 7), (px + 19, py + 17)], tint(rock, '#efe2bf', 0.35))
                self.polygon([(px + 19, py + 17), (px + 29, py + 7), (px + 36, py + 27), (px + 24, py + 33)], tint(rock, '#45594f', 0.25))
                self.line([(px + 7, py + 25), (px + 17, py + 20), (px + 22, py + 25)], tint(rock, '#253e39', 0.22), 1)
                if seed < 4:
                    self.oval(px + 3, py + 24, 13, 6, '#849d68' if w.mapid == 0 else '#ad996c')
        for p, (resource, amount) in w.deposits.items():
            x, y = self.point((p[0] + 0.5, p[1] + 0.5))
            c = {'metal': '#b3c5cd', 'circuits': '#e4b16d', 'crystal': '#aa96dc'}[resource]
            self.oval(x - 17, y + 2, 36, 15, '#839a75' if w.mapid != 1 else '#b29a75')
            for i, (dx, dy, s) in enumerate(((-9, 5, 9), (1, 0, 14), (10, 8, 8))):
                body = tint(c, '#7b8979', 0.8) if amount <= 0 else c
                self.polygon([(x + dx - s * 0.6, y + dy), (x + dx - s * 0.3, y + dy - s), (x + dx + s * 0.35, y + dy - s * 1.35), (x + dx + s * 0.7, y + dy - 2), (x + dx, y + dy + 5)], body, '#72836e', 0.5)
                self.polygon([(x + dx - s * 0.3, y + dy - s), (x + dx + s * 0.35, y + dy - s * 1.35), (x + dx, y + dy + 3)], tint(body, '#f5f9df', 0.5))
                self.line([(x + dx, y + dy + 3), (x + dx + s * 0.35, y + dy - s * 1.35)], tint(body, '#ffffff', 0.6), 1)
            if amount > 0 and resource == 'crystal':
                a = self.real_time * 1.4 + p[0]
                px = x + math.sin(a) * 12
                py = y - 13 + math.cos(a * 1.7) * 5
                self.line([(px - 2, py), (px + 2, py)], '#f5e5ff', 1)
                self.line([(px, py - 2), (px, py + 2)], '#f5e5ff', 1)

    def close(self):
        if self.texture_bank is not None:
            self.texture_bank.close()
        super().close()

    def minimap_bounds(self):
        return LEFT + 13, TOP + 14, 164, 137

    def draw_minimap(self):
        if self.camera.zoom < 1.12:
            return
        x, y, width, height = self.minimap_bounds()
        inner_x = x + 9
        inner_y = y + 22
        inner_w = width - 18
        inner_h = 88
        self.roundrect(x + 3, y + 4, width, height, '#102833', r=9)
        self.roundrect(x, y, width, height, '#234350', '#8fb6b7', r=9)
        self.text(x + 10, y + 7, 'TACTICAL VIEW', 7, '#d8e4cb', True)
        self.rect(inner_x, inner_y, inner_w, inner_h, '#859b7d')
        cell_w = inner_w / NX
        cell_h = inner_h / NY
        for gx, gy in self.world.terrain:
            color = '#5c98ad' if self.world.mapid == 2 else '#647a70'
            self.rect(inner_x + gx * cell_w, inner_y + gy * cell_h,
                      cell_w + .3, cell_h + .3, color)
        for building in self.world.buildings.values():
            color = '#c0d9ce' if building.kind < 12 else '#97b7b4'
            self.rect(inner_x + building.x * cell_w,
                      inner_y + building.y * cell_h,
                      max(2, cell_w * .7), max(2, cell_h * .7), color)
        for enemy in self.world.enemies:
            self.oval(inner_x + enemy.x * cell_w - 1,
                      inner_y + enemy.y * cell_h - 1,
                      2.5, 2.5, '#f2b098')
        self.oval(inner_x + self.world.corepos[0] * cell_w - 2,
                  inner_y + self.world.corepos[1] * cell_h - 2,
                  4, 4, '#ffe4a5')
        view_w = NX / self.camera.zoom
        view_h = NY / self.camera.zoom
        center_x = (self.camera.x - LEFT) / TILE
        center_y = (self.camera.y - TOP) / TILE
        view_x = inner_x + (center_x - view_w / 2) * cell_w
        view_y = inner_y + (center_y - view_h / 2) * cell_h
        self.rect(view_x, view_y, view_w * cell_w, view_h * cell_h,
                  '', '#f1f6d8', 1)
        self.buttons.append(((inner_x, inner_y, inner_w, inner_h),
                             ('minimap',), True))
        self.button(x + 9, y + 115, width - 18, 17,
                    'RESET VIEW [F]', ('view',), size=7)

    def recenter_from_minimap(self):
        x, y, width, height = self.minimap_bounds()
        inner_x = x + 9
        inner_y = y + 22
        inner_w = width - 18
        inner_h = 88
        u = max(0, min(1, (self.hover[0] - inner_x) / inner_w))
        v = max(0, min(1, (self.hover[1] - inner_y) / inner_h))
        self.camera.x = LEFT + u * NX * TILE
        self.camera.y = TOP + v * NY * TILE
        self.camera.clamp()

    def render_terrain(self):
        texture_revision = tuple(self.texture_bank.cache) if self.texture_bank is not None else ()
        key = (texture_revision,) + (self.world.mapid, self.world.nav_version, self.show_grid, self.build is not None, tuple(((p, d[1] > 0) for p, d in self.world.deposits.items())), round(self.camera.x, 3), round(self.camera.y, 3), round(self.camera.zoom, 4), round(self.camera.shake_x, 2), round(self.camera.shake_y, 2), self.scale, self.offset)
        if key == getattr(self, '_terrain_key', None):
            self.canvas.reuse_layer('terrain')
            return
        self._terrain_key = key
        self.canvas.set_layer('terrain')
        self.draw_environment(self.world)
        for b in self.world.buildings.values():
            x, y = self.point(b.pos)
            if b.role not in ('wall', 'gate'):
                self.roundrect(x - 17, y - 13, 34, 28, '#9ca897', '#d2d4b1', r=5)
                self.line([(x - 12, y + 8), (x + 12, y + 8)], '#7d9586', 1)
        for p in self.world.connected_relays():
            b = self.world.buildings[p]
            x, y = self.point(b.pos)
            sources = [self.world.corepos] + [(q[0] + 0.5, q[1] + 0.5) for q in self.world.connected_relays() if q != p]
            nearest = min(sources, key=lambda q: distance(q, b.pos))
            if distance(nearest, b.pos) <= 7:
                ex, ey = self.point(nearest)
                self.line([(x, y), (ex, ey)], '#c1caa0', 2, dash=(3, 6))

    def render_ground(self):
        self.canvas.set_layer('ground')
        for x, y in self.world.spawns:
            px, py = self.point((x + 0.5, y + 0.5))
            self.oval(px - 15, py - 11, 30, 22, '#746e54', '#d9af76', 1)
            self.oval(px - 10, py - 7, 20, 14, '#4f5846')
            if self.world.active:
                r = 14 + (math.sin(self.real_time * 3 + x) + 1) * 4
                self.oval(px - r, py - r * 0.7, 2 * r, 1.4 * r, '', '#efd398', 0.8)
        for h in self.world.hazards:
            x, y = self.point(h['pos'])
            r = h['radius'] * TILE
            self.oval(x - r, y - r * 0.6, 2 * r, 1.2 * r, '', '#cfe08d' if h.get('enemy') else '#eeb271', 2)
            for i in range(4):
                a = i * 1.7 + self.real_time
                xx = x + math.cos(a) * r * 0.5
                yy = y + math.sin(a) * r * 0.3
                self.oval(xx - 3, yy - 2, 6, 4, '#c2cf8a' if h.get('enemy') else '#f5bd7e')
        if self.quality:
            if self.world.mapid == 2:
                for gx, gy in list(self.world.terrain)[::3]:
                    px, py = self.point((gx + 0.5, gy + 0.5))
                    drift = math.sin(self.real_time * 1.5 + gx + gy) * 3
                    self.line([(px - 7 + drift, py), (px + 4 + drift, py), (px + 9 + drift, py - 2)], '#b4e1dd', 0.8)
            else:
                for i in range(20):
                    gx, gy = ((i * 7 + 3) % NX, (i * 11 + 2) % NY)
                    if (gx, gy) in self.world.terrain or (gx, gy) in self.world.buildings:
                        continue
                    px, py = self.point((gx + 0.5, gy + 0.5))
                    sway = math.sin(self.real_time * 1.7 + i) * 2
                    self.line([(px, py + 4), (px + sway, py - 5)], '#849d6b', 1)
        if self.build is not None:
            self.draw_build_network()

    def draw_build_network(self):
        for p, radius in [(self.world.corepos, 7)] + [((x + 0.5, y + 0.5), 5) for x, y in self.world.connected_relays()]:
            x, y = self.point(p)
            rr = radius * TILE
            self.oval(x - rr, y - rr, 2 * rr, 2 * rr, '', '#d4e9bb', 1)

    def render_core(self):
        x, y = self.point(self.world.corepos)
        self.sprite(25, x, y - 13, 74)
        pulse = 7 + math.sin(self.real_time * 3) * 1.8
        self.oval(x - pulse, y + 5 - pulse * 0.35, 2 * pulse, pulse * 0.7, '', '#b4f8f1', 1)

    def render_actors(self):
        self.canvas.set_layer('actors')
        objects = []
        for b in self.world.buildings.values():
            objects.append((b.y + 0.5, 0, b))
        objects.append((self.world.corepos[1], 1, None))
        for e in self.world.enemies:
            objects.append((e.y + (100 if e.flying else 0), 2, e))
        for _, kind, obj in sorted(objects, key=lambda entry: (entry[0], entry[1])):
            if kind == 0:
                self.draw_robot(obj, *self.point(obj.pos))
            elif kind == 1:
                self.render_core()
            else:
                self.draw_bug(obj, *self.point(obj.pos))

    def render_projectiles(self):
        self.canvas.set_layer('effects')
        for p in self.world.projectiles:
            if p['age'] < 0:
                continue
            x, y = self.point((p['x'], p['y']))
            dx, dy = (p['dest'][0] - p['x'], p['dest'][1] - p['y'])
            angle = math.atan2(dy, dx)
            if p['role'] == 'mortar':
                total = max(0.1, distance(p['origin'], p['dest']))
                progress = min(1, distance(p['origin'], (p['x'], p['y'])) / total)
                self.oval(x - 4, y - 2, 8, 4, '#6e856e')
                y -= math.sin(progress * math.pi) * 65
            color = '#c9f8ff' if p['role'] == 'air' else '#dec5ff' if p['role'] == 'sniper' else '#ffdf93'
            length = 20 if p['role'] == 'sniper' else 11
            self.line([(x - math.cos(angle) * length, y - math.sin(angle) * length), (x, y)], color, 1.6)
            self.oval(x - 2, y - 2, 4, 4, '#fff6d0')
            if p['role'] == 'rocket':
                self.line([(x - math.cos(angle) * 10, y - math.sin(angle) * 10), (x, y)], '#ffb879', 4)
                self.oval(x - 3, y - 3, 6, 6, '#e6e1c5')
        if self.quality:
            effects = self.world.effects[-220:]
        else:
            effects = self.world.effects[-80:]
        for effect in effects:
            self.draw_effect(effect)
        if self.quality:
            for xx, yy, speed, phase in self.ambient[:16]:
                px = LEFT + (xx + self.real_time * speed * 5) % (NX * TILE)
                py = TOP + (yy - self.real_time * speed * 3) % (NY * TILE)
                self.oval(px, py, 1.8, 1.8, '#edf0c6')

    def render_selection(self):
        self.canvas.set_layer('effects')
        b = self.world.buildings.get(self.selected)
        if b:
            x, y = self.point(b.pos)
            radius = b.stats()['range'] * TILE
            if radius:
                self.oval(x - radius, y - radius, radius * 2, radius * 2, '', b.spec['color'], 1)
            self.roundrect(x - 19, y - 17, 38, 34, '', '#eff9d9', r=5, width=1.5)
            self.oval(x - 12, y + 14, 24, 6, '', b.spec['color'], 1)
        if not self.on_board(self.hover) or self.build is None:
            return
        gx, gy = self.tile(self.hover)
        if not (0 <= gx < NX and 0 <= gy < NY):
            return
        if self.wall_start is not None:
            self.render_wall_preview()
            return
        x, y = self.point((gx + 0.5, gy + 0.5))
        if isinstance(self.build, int):
            error = self.world.can_place(gx, gy, self.build)
            self.preview_error = error
            color = '#ffb2a2' if error else '#d9ffbd'
            self.roundrect(x - 16, y - 16, 32, 32, '', color, r=4, width=2)
            radius = SPECS[self.build].get('range', 0) * TILE
            if radius:
                self.oval(x - radius, y - radius, 2 * radius, 2 * radius, '', color, 0.8)
            if not error:
                self.draw_robot(Building(gx, gy, self.build), x, y)
        else:
            self.roundrect(x - 16, y - 16, 32, 32, '', '#ffe3a0', r=4, width=2)

    def render_wall_preview(self):
        points = line_tiles(self.wall_start, self.wall_end or self.wall_start)
        valid = 0
        affordable = min(self.world.money // 12, self.world.materials['metal'] // 12)
        for gx, gy in points:
            if (gx, gy) in self.world.buildings:
                continue
            x, y = self.point((gx + 0.5, gy + 0.5))
            ok = not self.world.can_place(gx, gy, 12) and valid < affordable
            if ok:
                valid += 1
            self.roundrect(x - 16, y - 16, 32, 32, '', '#dbffc2' if ok else '#ffad98', r=3, width=2)
            if ok:
                self.line([(x - 8, y), (x + 8, y)], '#f4ffd7', 2)
        x, y = self.point((self.wall_end[0] + 0.5, self.wall_end[1] + 0.5))
        self.text(x, y - 34, f'{valid} walls  ${valid * 12}  /  {valid * 12} metal', 10, '#173e3d', True, anchor='center')

    def render_masks(self):
        self.canvas.set_layer('masks')
        self.rect(0, 0, WIDTH, TOP - 6, COLORS['bg'])
        self.rect(0, TOP - 6, LEFT - 5, HEIGHT, COLORS['bg'])
        self.rect(LEFT + NX * TILE + 5, TOP - 6, WIDTH, HEIGHT, COLORS['bg'])
        self.rect(0, TOP + NY * TILE + 5, WIDTH, HEIGHT, COLORS['bg'])

    def header(self):
        w = self.world
        self.gradient(0, 0, WIDTH, 111, '#243b4b', '#142839', 14)
        self.text(24, 17, 'project-swarmfall', 23, '#eef2df', True)
        self.text(26, 53, MAP_NAMES[w.mapid].upper(), 9, '#a3bec6', True)
        resources = [('DOLLARS', f'${w.money:,}', '#f5d28a'), ('METAL', str(w.materials['metal']), '#c9d9df'), ('CIRCUITS', str(w.materials['circuits']), '#e0b484'), ('CRYSTALS', str(w.materials['crystal']), '#c3b0ed')]
        for i, (label, value, color) in enumerate(resources):
            x = 350 + i * 139
            self.text(x, 16, label, 8, '#9eb9c4', True)
            self.text(x, 36, value, 21, color, True)
            self.polygon([(x - 15, 23), (x - 10, 18), (x - 5, 23), (x - 10, 28)], color)
        supply, used = w.power()
        self.text(927, 16, 'POWER', 8, '#a4bec5', True)
        self.text(927, 38, f'{used}/{supply}', 17, '#ffb09b' if used > supply else '#a1e5de', True)
        self.text(1040, 16, 'CORE INTEGRITY', 8, '#a4bec5', True)
        self.roundrect(1040, 43, 205, 9, '#3e5560', r=3)
        self.roundrect(1040, 43, max(0.1, 205 * w.corehp / w.coremax), 9, '#a5dfb1', r=3)
        self.text(1257, 36, f'{int(w.corehp):,} / {w.coremax:,}', 10, '#bad0d1')
        message = w.message if w.message_time else 'Scroll to zoom · Middle-drag to pan · F resets view · F2 opens the codex'
        self.text(26, 86, message, 11, '#ead09a' if w.message_time else '#a6c2c8')
        self.line([(24, 109), (1416, 109)], '#466575', 1)

    def sidebar(self):
        super().sidebar()
        w = self.world
        b = w.buildings.get(self.selected)
        if b and b.kind < 12:
            self.button(PANEL + 4, 733, 408, 28, 'TARGET: ' + getattr(b, 'target_mode', 'first').upper() + '  •  CLICK TO CYCLE', ('target',), size=9)
        self.rect(PANEL, 879, 420, 61, COLORS['bg'])
        self.button(PANEL, 888, 99, 35, 'CODEX [F2]', ('codex',), size=8)
        self.button(PANEL + 106, 888, 99, 35, 'UNDO', ('undo',), enabled=not w.active, size=9)
        self.button(PANEL + 212, 888, 99, 35, 'VIEW [F]', ('view',), size=8)
        self.button(PANEL + 318, 888, 99, 35, 'SAVE [F5]', ('save',), enabled=not w.active, size=8)
        self.text(PANEL + 2, 927, f'{w.kills} defeated   •   {len(w.earned)}/{len(ACHIEVEMENTS)} achievements   •   {self.camera.zoom:.1f}× view', 8, '#819fac')
        if self.build is not None:
            self.text(29, 872, 'Right-click / Esc: stop building  •  Click an existing unit to inspect  •  Ctrl+Z: undo unused builds', 9, '#adcad1')
        self.render_wave_forecast()

    def render_wave_forecast(self):
        x, y = self.hover
        if not (25 <= x <= 277 and 888 <= y <= 924):
            return
        wave = min(40, self.world.wave + 1)
        plan = WAVE_PLANS[wave - 1]
        self.canvas.set_layer('hud')
        self.roundrect(29, 724, 356, 139, '#203c49', '#a0c7bb', r=10)
        self.text(46, 741, f'NEXT / WAVE {wave:02d}', 9, '#a4dcbb', True)
        self.text(46, 762, plan.name, 17, '#f1e6c8', True)
        self.text(46, 792, plan.description, 11, '#b5d0ce', width=319)
        self.text(46, 833, 'Starts when you press Space or enable autoplay.', 8, '#98b8c1')

    def inspector(self, b, x, y, width):
        super().inspector(b, x, y, width)
        if b.kind < 12:
            self.text(x + 4, 849, f"Kills: {getattr(b, 'kill_count', 0)}   Damage: {getattr(b, 'damage_dealt', 0):,.0f}   C copies this unit", 8, '#a1bfc5')

    def draw_title_scene(self):
        t = self.real_time
        if self.texture_bank is not None:
            image = self.texture_bank.get(self.title_map, 1040 * self.scale)
            self.canvas.create_image(1120, 560, image=image, anchor='center')
        else:
            self.rect(600, 160, 840, 780, '#9eb88a')
        self.canvas.create_line(660, 820, 830, 715, 970, 620, 1140, 660, 1450, 480, fill='#c5bd95', width=103 * self.scale, smooth=True, splinesteps=24)
        self.canvas.create_line(660, 820, 830, 715, 970, 620, 1140, 660, 1450, 480, fill='#d0c49f', width=63 * self.scale, smooth=True, splinesteps=24)
        for i in range(29):
            xx = 615 + i * 137 % 825
            yy = 370 + i * 89 % 560
            sway = math.sin(t * 1.6 + i) * 4
            self.line([(xx, yy + 9), (xx + sway - 4, yy - 6)], '#7e9c69', 2)
            self.line([(xx + 5, yy + 9), (xx + sway + 7, yy - 3)], '#87a56d', 2)
            if i % 5 == 0:
                self.oval(xx + sway - 8, yy - 10, 7, 7, '#eadbae')
        for xx, yy, sz in ((1350, 290, 75), (1000, 315, 45), (1390, 770, 80), (730, 430, 50)):
            self.oval(xx - sz, yy + sz * 0.4, sz * 2, sz * 0.7, '#758c6b')
            self.polygon([(xx - sz, yy + sz * 0.4), (xx - sz * 0.6, yy - sz * 0.3), (xx, yy - sz * 0.8), (xx + sz * 0.7, yy - sz * 0.2), (xx + sz, yy + sz * 0.5)], '#788d7a')
            self.polygon([(xx - sz * 0.6, yy - sz * 0.3), (xx, yy - sz * 0.8), (xx + sz * 0.7, yy - sz * 0.2), (xx + sz * 0.1, yy + sz * 0.1)], '#a2b09a')
        for i, (xx, yy, kind, sz) in enumerate(((855, 580, 0, 2.4), (1030, 430, 4, 1.9), (1225, 815, 7, 2.1), (1100, 830, 9, 1.6))):
            b = Building(0, 0, kind)
            b.angle = math.sin(t * 0.7 + i) * 0.35 + 0.6
            b.animation = 0.1 if math.sin(t * 5 + i) > 0.7 else 0
            self.draw_robot(b, xx, yy, sz)
            if i < 2:
                phase = (t * 1.7 + i * 0.4) % 1
                sx, sy = (xx + 35, yy + 14)
                ex, ey = (xx + 220, yy + 150)
                self.line([(sx + (ex - sx) * phase, sy + (ey - sy) * phase), (sx + (ex - sx) * (phase + 0.04), sy + (ey - sy) * (phase + 0.04))], '#ffe4a1', 3)
        for i, (name, xx, yy, sz) in enumerate((('Stag Beetle', 1350, 600, 2.8), ('Ant', 980, 730, 2.0), ('Mantis', 1280, 390, 2.4), ('Wasp', 1120, 260, 2.1), ('Ladybug', 820, 860, 2.3))):
            e = Enemy(name, xx / 30, yy / 30, 1)
            e.angle = math.pi + 0.2 * math.sin(t * 0.5 + i)
            self.draw_bug(e, xx + math.sin(t * 0.4 + i) * 14, yy + math.cos(t * 0.7 + i) * 7, sz)
        for xx, yy, speed, phase in self.ambient:
            px = 650 + (xx * 0.65 + t * speed * 5) % 790
            py = (yy - t * speed * 3) % 900
            rr = 1.2 + math.sin(t + phase) * 0.6
            self.oval(px - rr, py - rr, rr * 2, rr * 2, '#dbe2ae')

    def title(self):
        super().title()
        self.rect(60, 754, 400, 186, '#112638')
        for i, (key, label) in enumerate((('relaxed', 'RELAXED'), ('standard', 'STANDARD'), ('veteran', 'VETERAN'))):
            self.button(76 + i * 121, 764, 113, 31, label, ('difficulty', key), accent='#b4d9ad' if self.difficulty == key else None, size=8)
        self.text(78, 812, '12 ROBOTS / 72 UPGRADES / 40 DISTINCT WAVES', 9, '#b7d1d1', True)
        self.text(78, 845, 'ENTER deploy   •   F2 robot and insect codex', 10, '#99bac2')
        if self.save_manager.exists():
            self.button(76, 884, 173, 32, 'CONTINUE BASE [F9]', ('load',), size=8)
        self.button(262, 884, 169, 32, 'EXPLORE CODEX', ('codex',), size=9)

    def overlay(self):
        super().overlay()
        if not self.world.outcome:
            y = 155 + (1 - ease(self.pause_age * 3)) * 45
            self.button(485, y + 568, 227, 34, 'SAVE BASE [F5]', ('save',), enabled=not self.world.active, size=9)
            self.button(727, y + 568, 228, 34, 'LOAD BASE [F9]', ('load',), enabled=self.save_manager.exists(), size=9)
        else:
            self.text(485, 738, f"Damage dealt: {self.world.record['damage']:,.0f}  •  Dollars invested: ${self.world.record['spent']:,.0f}", 9, '#bad1d1')

    def draw_notices(self, dt):
        while self.world.notice_queue:
            notice = self.world.notice_queue.pop(0)
            if len(self.notices) >= 3:
                self.notices.pop(0)
            self.notices.append(notice)
        for notice in self.notices:
            notice.update(dt)
        self.notices = [n for n in self.notices if n.remaining > 0]
        for index, notice in enumerate(reversed(self.notices)):
            alpha = min(ease(notice.age / 0.22), ease(notice.remaining / 0.3))
            xx = LEFT + NX * TILE - 337 + (1 - alpha) * 70
            yy = TOP + 14 + index * 66
            self.roundrect(xx + 3, yy + 4, 318, 57, '#152d35', r=9)
            self.roundrect(xx, yy, 318, 57, '#254450', notice.color, r=9)
            self.text(xx + 13, yy + 11, notice.title, 10, notice.color, True, width=290)
            self.text(xx + 13, yy + 32, notice.body, 8, '#c4dad7', width=290)

    def draw_tooltip(self, dt):
        if self.selected or self.show_help or self.show_codex or self.paused:
            self.tooltip_timer = 0
            return
        card = None
        for rect, action, enabled in self.buttons:
            if action[0] != 'build' or not isinstance(action[1], int):
                continue
            x, y, w, h = rect
            if x <= self.hover[0] <= x + w and y <= self.hover[1] <= y + h:
                card = action[1]
                break
        if card != self.tooltip_key:
            self.tooltip_key = card
            self.tooltip_timer = 0
        self.tooltip_timer += dt
        if card is None or self.tooltip_timer < 0.55:
            return
        spec = SPECS[card]
        x = LEFT + NX * TILE - 362
        y = TOP + NY * TILE - 190
        self.roundrect(x, y, 347, 173, '#203947', '#95bfc2', r=12)
        self.text(x + 18, y + 16, spec['name'], 18, spec['color'], True)
        self.text(x + 18, y + 49, f"${spec['price']}  •  {spec['metal']} metal  •  {spec['circuits']} circuits", 10, '#eed6a4')
        if card < 12:
            subtitle, description = ROBOT_GUIDE[spec['role']]
            self.text(x + 18, y + 79, subtitle.upper(), 9, '#b6d9c8', True)
            self.text(x + 18, y + 101, description, 11, '#c1d4d5', width=309)
        else:
            notes = {'wall': 'Durable route control. Drag to preview an entire line before placing it.', 'gate': 'Select a placed gate to open or close the path.', 'generator': 'Eight power capacity and five tiles of construction reach when connected.', 'mine': 'Automates material extraction from deposits within two tiles.', 'shield': 'Recharges shields on nearby structures to absorb incoming damage.'}
            self.text(x + 18, y + 82, notes[spec['role']], 11, '#c1d4d5', width=309)

    def codex(self):
        self.canvas.set_layer('modal')
        self.canvas.create_rectangle(0, 0, WIDTH, HEIGHT, fill='#081c2a', outline='', stipple='gray50')
        self.roundrect(150, 72, 1140, 794, '#162f42', '#618594', r=22)
        self.gradient(170, 89, 1100, 115, '#294c59', '#162f42', 14)
        self.text(188, 105, 'SWARMFALL FIELD CODEX', 25, '#f0e2b9', True)
        self.text(189, 150, 'Know your machines. Know the swarm.', 12, '#a9c9cf')
        self.buttons = []
        for i, (key, label) in enumerate((('robots', 'ROBOTS'), ('bugs', 'INSECTS'), ('achievements', 'ACHIEVEMENTS'))):
            self.button(188 + i * 225, 191, 213, 39, label, ('codextab', key), accent=COLORS['gold'] if self.codex_tab == key else None, size=10)
        self.button(1096, 105, 153, 37, 'CLOSE [F2]', ('codex',), size=9)
        if self.codex_tab == 'achievements':
            self.codex_achievements()
        else:
            self.codex_units()

    def codex_units(self):
        is_robot = self.codex_tab == 'robots'
        entries = ROBOTS if is_robot else list(BUGS)
        selected = min(self.codex_index, len(entries) - 1)
        for i, entry in enumerate(entries):
            name = entry['name'] if is_robot else entry
            self.button(188, 254 + i * 39, 282, 32, name, ('codexindex', i), accent=COLORS['blue'] if i == selected else None, size=10)
        x = 507
        self.roundrect(x, 254, 738, 300, '#223d49', '#375b66', r=12)
        if is_robot:
            spec = entries[selected]
            self.sprite(selected, x + 181, 395, 256)
            subtitle, description = ROBOT_GUIDE[spec['role']]
            self.text(x + 363, 279, spec['name'], 27, spec['color'], True)
            self.text(x + 365, 329, subtitle, 13, '#d9ddbd', True)
            self.text(x + 365, 367, description, 12, '#bdd6d8', width=339)
            self.text(x + 365, 470, f"${spec['price']}  ·  {spec['metal']} metal  ·  {spec['circuits']} circuits", 11, '#efd39d')
            self.text(x + 365, 500, f"Range {spec['range']:.1f}  ·  Power {spec['power']}", 10, '#9dbfc6')
            for path, (name, upgrades) in enumerate(spec['paths']):
                xx = x + path * 376
                self.text(xx + 5, 578, name.upper(), 12, COLORS['gold'] if path == 0 else COLORS['purple'], True)
                for tier, u in enumerate(upgrades):
                    yy = 609 + tier * 66
                    self.text(xx + 5, yy, f"{tier + 1}. {u['name']}  /  ${u['price']}", 10, '#e8eddf', True)
                    self.text(xx + 5, yy + 22, u['description'], 10, '#9fbfc7', width=344)
        else:
            name = entries[selected]
            spec = BUGS[name]
            subtitle, description, counter = BUG_GUIDE[name]
            self.sprite(12 + selected, x + 182, 397, 256)
            self.text(x + 363, 279, name, 25, spec[4], True, width=339)
            self.text(x + 365, 337, subtitle, 13, '#dcdfbd', True)
            self.text(x + 365, 377, description, 12, '#bfd5d5', width=337)
            self.text(x + 365, 466, f'Counter: {counter}', 11, '#b5e1bf', True, width=330)
            self.text(x + 15, 584, 'FIELD NOTES', 12, COLORS['gold'], True)
            facts = [f'Base health: {spec[0]:,} (increases with waves)', f'Movement: {spec[1]:.2f} tiles / second', f'Bounty: ${spec[2]} before command bonuses', 'Flying insect: ignores terrain and walls' if name in FLIERS else 'Ground insect: follows open routes, attacks barriers when blocked', 'Appears as the final boss on wave 40' if name == 'Goliath Beetle' else 'Appears gradually as the forty-wave campaign progresses']
            for i, fact in enumerate(facts):
                self.text(x + 15, 619 + i * 33, fact, 12, '#b6cfd1')

    def codex_achievements(self):
        page = self.codex_page
        for i, achievement in enumerate(ACHIEVEMENTS[page * 8:page * 8 + 8]):
            col = i % 2
            row = i // 2
            x = 188 + col * 538
            y = 258 + row * 129
            complete = achievement.key in self.world.earned
            self.roundrect(x, y, 521, 114, '#213c4a', '#b3cf9f' if complete else '#365867', r=10)
            self.text(x + 16, y + 13, achievement.title, 15, '#c7e6b4' if complete else '#e5e9d9', True)
            self.text(x + 16, y + 42, achievement.description, 11, '#a9c5cb')
            value = min(achievement.target, self.world.achievement_progress(achievement))
            self.roundrect(x + 16, y + 76, 354, 6, '#36515e', r=2)
            self.roundrect(x + 16, y + 76, max(0.1, 354 * value / achievement.target), 6, '#b1d8a9' if complete else '#79bbcb', r=2)
            self.text(x + 386, y + 72, 'DONE' if complete else f'{int(value)} / {achievement.target}', 9, '#b8d3c9', True)
            self.text(x + 16, y + 91, f'Reward: ${achievement.reward}', 8, '#d8c28f')
        for page_index in range(3):
            self.button(188 + page_index * 92, 798, 80, 32, str(page_index + 1), ('codexpage', page_index), accent=COLORS['gold'] if page == page_index else None, size=9)
        self.text(526, 806, f'{len(self.world.earned)} of {len(ACHIEVEMENTS)} earned this mission', 11, '#aec9ce')

    def frame(self):
        if not getattr(self, 'ready', False):
            if not self.closed:
                self.root.after(16, self.frame)
            return
        if self.closed:
            return
        start = time.perf_counter()
        dt = min(0.1, start - self.last)
        self.last = start
        self.real_time += dt
        self.pause_age += dt
        self.title_age += dt
        self.frame_counter += 1
        self.camera.update(dt)
        if self.texture_bank is not None:
            self.texture_bank.pump()
        if self.transition:
            self.transition['age'] += dt
            if self.transition['age'] >= 0.42 and (not self.transition['switched']):
                action = self.transition['action']
                self.transition['switched'] = True
                App.action(self, action)
                if action[0] == 'map':
                    self.world = SmoothWorld(action[1], self.difficulty)
                self.camera.reset()
                self.notices = []
                self.accumulator = 0
                self.wave_banner = 0
                self.previous_wave = 0
                self.title_age = 0
                self.show_help = self.show_codex = False
            if self.transition['age'] >= 0.88:
                self.transition = None
        playing = self.state == 'play' and (not self.paused) and (not self.world.outcome) and (not self.show_help) and (not self.show_codex) and (not self.transition)
        if playing:
            self.accumulator += dt * self.speed
            steps = 0
            while self.accumulator >= 1 / 60 and steps < 15:
                self.world.update(1 / 60)
                self.accumulator -= 1 / 60
                steps += 1
            if steps == 15:
                self.accumulator = min(self.accumulator, 1 / 60)
            if self.selected not in self.world.buildings:
                self.selected = None
            if self.world.wave != self.previous_wave:
                self.previous_wave = self.world.wave
                self.wave_banner = 3.3
                self.banner_text = 'FINAL WAVE' if self.world.wave == 40 else f'WAVE {self.world.wave:02d}'
            self.wave_banner = max(0, self.wave_banner - dt)
        else:
            self.accumulator = 0
        cw, ch = (max(1, self.canvas.winfo_width()), max(1, self.canvas.winfo_height()))
        self.scale = min(cw / WIDTH, ch / HEIGHT)
        self.offset = ((cw - WIDTH * self.scale) / 2, (ch - HEIGHT * self.scale) / 2)
        self.camera.shake_x = self.camera.shake_y = 0
        if self.screen_shake and playing:
            strength = min(4, self.world.shake)
            self.camera.shake_x = math.sin(self.real_time * 53) * strength
            self.camera.shake_y = math.cos(self.real_time * 47) * strength * 0.6
        self.canvas.begin()
        self.buttons = []
        if self.state == 'title':
            self._terrain_key = None
            self.canvas.set_layer('hud')
            self.title()
        else:
            self.render_terrain()
            self.render_ground()
            self.render_actors()
            self.render_projectiles()
            self.render_selection()
            self.render_masks()
            self.canvas.set_layer('hud')
            self.header()
            self.sidebar()
            self.draw_minimap()
            self.draw_notices(dt)
            self.draw_tooltip(dt)
            if self.wave_banner > 0:
                self.wave_overlay()
            else:
                boss = next((e for e in self.world.enemies if e.name == 'Goliath Beetle'), None)
                if boss:
                    self.boss_bar(boss)
            if self.paused or self.world.outcome:
                self.canvas.set_layer('modal')
                self.overlay()
        if self.show_help:
            self.canvas.set_layer('modal')
            self.guide()
        if self.show_codex:
            self.codex()
        self.canvas.set_layer('transition')
        self.draw_transition()
        self.canvas.end()
        self.last_frame_ms = (time.perf_counter() - start) * 1000
        if self.last_frame_ms < 11:
            self.sprite_bank.warm(0.0015)
        frame_time = time.perf_counter() - start
        delay = max(1, round((1 / 60 - frame_time) * 1000))
        self.root.after(delay, self.frame)
if __name__ == '__main__':
    PremiumApp().run()
